            EntityGroundVehicle craft=null;for(Entity e:world.loadedEntityList)if(e instanceof EntityGroundVehicle&&Math.abs(e.posX+128.7567)<2&&Math.abs(e.posZ-52.7564)<2)craft=(EntityGroundVehicle)e;
